use agentchat_core::{RichReply, Role};
use agentchat_slack::{events, rendering};
use serde_json::{json, Value};

fn event() -> Value {
    json!({"team_id":"T1","event_id":"Ev1","event":{
        "type":"app_mention","channel":"C1","user":"U1","ts":"1.000001",
        "text":"<@BOT> hi 🦀 <@OTHER>"}})
}

#[test]
fn shared_python_reference_fixtures_match_exactly() {
    let fixtures: Value =
        serde_json::from_str(include_str!("../../../conformance/slack-events.json")).unwrap();
    for case in fixtures.as_array().unwrap() {
        let actual = events::normalize(
            &case["payload"],
            case["bot_user_id"].as_str().unwrap(),
            case["workspace_id"].as_str().unwrap(),
        );
        assert_eq!(
            serde_json::to_value(actual).unwrap(),
            case["expected"],
            "{}",
            case["name"]
        );
    }
}

#[test]
fn messages_preserve_identity_and_only_strip_our_mention() {
    let payload = event();
    let message = events::normalize(&payload, "BOT", "T1").unwrap();
    assert_eq!(message.id.as_ref(), "slack:T1:C1:1.000001");
    assert_eq!(message.conversation_id.as_ref(), "slack:T1:C1:1.000001");
    assert_eq!(message.thread_id.as_deref(), Some("1.000001"));
    assert_eq!(message.text, "hi 🦀 <@OTHER>");
    assert!(message.addressed);
    assert_eq!(message.role, Role::User);
    let mut duplicate = payload;
    duplicate["event_id"] = json!("another-envelope");
    assert_eq!(
        events::normalize(&duplicate, "BOT", "T1").unwrap().id,
        message.id
    );
}

#[test]
fn direct_messages_share_conversation_but_preserve_explicit_threads() {
    let mut payload = event();
    payload["event"]["type"] = json!("message");
    payload["event"]["channel_type"] = json!("im");
    let first = events::normalize(&payload, "BOT", "T1").unwrap();
    assert_eq!(first.conversation_id.as_ref(), "slack:T1:C1");
    assert_eq!(first.thread_id, None);
    payload["event"]["ts"] = json!("2.000002");
    payload["event"]["thread_ts"] = json!("1.000001");
    let reply = events::normalize(&payload, "BOT", "T1").unwrap();
    assert_eq!(reply.conversation_id, first.conversation_id);
    assert_eq!(reply.thread_id.as_deref(), Some("1.000001"));
}

#[test]
fn ignores_foreign_workspace_self_bots_and_mutations() {
    assert!(events::normalize(&event(), "BOT", "T2").is_none());
    for (field, value) in [
        ("user", json!("BOT")),
        ("bot_id", json!("B1")),
        ("bot_profile", json!({})),
        ("subtype", json!("message_changed")),
        ("thread_ts", json!(123)),
        ("text", json!(123)),
        ("channel", json!("")),
    ] {
        let mut payload = event();
        payload["event"][field] = value;
        assert!(
            events::normalize(&payload, "BOT", "T1").is_none(),
            "{field}"
        );
    }
}

#[test]
fn unaddressed_channel_threads_require_subscription() {
    let mut payload = event();
    payload["event"]["type"] = json!("message");
    payload["event"]["channel_type"] = json!("channel");
    payload["event"]["text"] = json!("follow up");
    assert!(events::normalize(&payload, "BOT", "T1").is_none());
    payload["event"]["thread_ts"] = json!("0.001");
    let message = events::normalize(&payload, "BOT", "T1").unwrap();
    assert!(!message.addressed);
    assert_eq!(message.metadata["requires_subscription"], true);
    assert_eq!(message.conversation_id.as_ref(), "slack:T1:C1:0.001");
}

#[test]
fn file_only_messages_keep_bounded_sanitized_references() {
    let mut payload = event();
    payload["event"]["text"] = json!("<@BOT>");
    payload["event"]["subtype"] = json!("file_share");
    payload["event"]["files"] = json!([
        {"id":"F1","name":"/tmp/..\\report\u{200d}\u{e000}.txt","size":10,"mimetype":"text/plain","url_private":"secret"},
        {"id":"F1","name":"duplicate"}, {"id":"../unsafe"}, {"id":"F2","size":true},
        {"id":"F3","name":"..."}, {"id":"F4"}]);
    let message = events::normalize(&payload, "BOT", "T1").unwrap();
    assert_eq!(message.attachments.len(), 3);
    assert_eq!(message.attachments[0].name.as_deref(), Some("report.txt"));
    assert_eq!(message.attachments[1].size, None);
    assert_eq!(message.attachments[2].name.as_deref(), Some("attachment"));
    assert!(!serde_json::to_string(&message).unwrap().contains("secret"));
}

#[test]
fn rendering_preserves_unicode_and_reopens_code_fences() {
    let text = format!("```rust\n{}\n```", "🦀".repeat(7000));
    let blocks = rendering::text_blocks(&text).unwrap();
    assert_eq!(blocks.len(), 3);
    for block in &blocks {
        let section = block["text"]["text"].as_str().unwrap();
        assert!(section.chars().count() <= 3000);
        assert_eq!(section.matches("```").count() % 2, 0);
        assert_eq!(block["expand"], true);
        assert_eq!(block["text"]["verbatim"], true);
    }
    assert_eq!(
        blocks
            .iter()
            .map(|b| b["text"]["text"].as_str().unwrap().matches('🦀').count())
            .sum::<usize>(),
        7000
    );
    assert!(rendering::text_blocks("   ").is_err());
    assert!(rendering::text_blocks(&"x".repeat(2992 * 50 + 1)).is_err());
}

#[test]
fn rich_payload_expands_sections_without_overriding_explicit_behavior() {
    let reply = RichReply {
        text: "fallback".into(),
        blocks: vec![
            json!({"type":"section","text":{"type":"plain_text","text":"one"}})
                .as_object()
                .unwrap()
                .clone(),
            json!({"type":"section","expand":false})
                .as_object()
                .unwrap()
                .clone(),
        ],
        attachments: Vec::new(),
    };
    let payload = rendering::rich_payload(&reply).unwrap();
    assert_eq!(payload["blocks"][0]["expand"], true);
    assert_eq!(payload["blocks"][1]["expand"], false);
    assert_eq!(payload["parse"], "none");
}

#[test]
fn mirror_uses_plain_text_and_escaped_fallback() {
    let message = events::normalize(&event(), "BOT", "T1").unwrap();
    let payload = rendering::mirror_payload(&message, "web").unwrap();
    assert_eq!(payload["blocks"][1]["text"]["type"], "plain_text");
    assert!(payload["text"].as_str().unwrap().contains("&lt;@OTHER&gt;"));
    assert_eq!(payload["mrkdwn"], false);
    let mut too_long = message;
    too_long.text = "🦀".repeat(2801);
    assert!(rendering::mirror_payload(&too_long, "web").is_err());
}

use std::sync::{
    atomic::{AtomicUsize, Ordering},
    Arc,
};
use std::time::Duration;

use agentchat_core::*;
use async_trait::async_trait;
use tokio::sync::{Mutex, Semaphore};

fn incoming(id: &str, conversation: &str) -> Message {
    Message {
        id: id.into(),
        conversation_id: conversation.into(),
        channel: "fake".into(),
        sender: Sender {
            id: "alice".into(),
            display_name: None,
        },
        text: id.into(),
        role: Role::User,
        metadata: Default::default(),
        thread_id: None,
        addressed: true,
        attachments: vec![],
    }
}

#[derive(Default)]
struct FakeChannel {
    calls: AtomicUsize,
    sent: Mutex<Vec<String>>,
    uncertain: bool,
    history: Option<Vec<Message>>,
    history_fails: bool,
    statuses: Mutex<Vec<String>>,
    status_supported: bool,
    status_fails: bool,
}

#[async_trait]
impl Channel for FakeChannel {
    fn name(&self) -> &str {
        "fake"
    }

    async fn set_status(&self, _source: &Message, status: &str) -> Result<bool> {
        if !self.status_supported {
            return Ok(false);
        }
        self.statuses.lock().await.push(status.to_owned());
        if self.status_fails {
            return Err(Error::Transport("Status unavailable".into()));
        }
        Ok(true)
    }

    async fn reply(&self, source: &Message, content: &str) -> Result<Message> {
        let sequence = self.calls.fetch_add(1, Ordering::SeqCst) + 1;
        self.sent.lock().await.push(content.to_owned());
        if self.uncertain {
            return Err(Error::Transport("Delivery outcome is unknown".into()));
        }
        Ok(Message {
            id: format!("reply:{sequence}").into(),
            sender: Sender {
                id: "bot".into(),
                display_name: None,
            },
            text: content.into(),
            role: Role::Assistant,
            ..source.clone()
        })
    }

    async fn thread_history(
        &self,
        _source: &Message,
        _limit: usize,
    ) -> Result<Option<Vec<Message>>> {
        if self.history_fails {
            return Err(Error::Transport("History unavailable".into()));
        }
        Ok(self.history.clone())
    }
}

#[test]
fn typed_turn_enforces_each_effect_and_keeps_empty_replies() {
    let mut turn = Turn::new();
    assert_eq!(turn.effect(), &TurnEffect::Claim);
    assert!(turn.resolve(TurnResult::ReplySent).is_err());
    assert_eq!(turn.effect(), &TurnEffect::Claim);
    turn.resolve(TurnResult::Claimed(true)).unwrap();
    assert_eq!(turn.effect(), &TurnEffect::AcquireConversation);
    turn.resolve(TurnResult::ConversationAcquired).unwrap();
    turn.resolve(TurnResult::IncomingAppended).unwrap();
    turn.resolve(TurnResult::HandlerCompleted(Some(String::new())))
        .unwrap();
    assert_eq!(turn.effect(), &TurnEffect::SendReply(String::new()));
    turn.resolve(TurnResult::ReplySent).unwrap();
    turn.resolve(TurnResult::ReplyAppended).unwrap();
    assert_eq!(turn.effect(), &TurnEffect::Complete);
    assert!(turn.resolve(TurnResult::Claimed(true)).is_err());
}

#[test]
fn duplicate_finishes_without_any_other_effect() {
    let mut turn = Turn::new();
    turn.resolve(TurnResult::Claimed(false)).unwrap();
    assert_eq!(turn.effect(), &TurnEffect::Complete);
}

#[test]
fn history_selection_preserves_root_and_current_turn() {
    assert_eq!(thread_history_indices(5, 3).unwrap(), vec![0, 3, 4]);
    assert_eq!(thread_history_indices(1, 3).unwrap(), vec![0]);
    assert!(thread_history_indices(5, 1).is_err());
    assert!(thread_history_indices(5, 101).is_err());
}

#[test]
fn memory_values_preserve_identity_and_zero_limit_matches_python() {
    let mut store = MemoryStore::new();
    let value = Arc::new(vec![1, 2, 3]);
    let conversation = ConversationId::from("example");
    assert!(store.claim(&MessageId::from("one")));
    assert!(!store.claim(&MessageId::from("one")));
    store.append(&conversation, value.clone());
    assert!(Arc::ptr_eq(
        &store.history(&conversation, Some(0))[0],
        &value
    ));
    assert!(store
        .history(&ConversationId::from("missing"), None)
        .is_empty());
}

#[test]
fn portable_ids_are_strings_and_optional_message_fields_have_defaults() {
    let message: Message = serde_json::from_value(serde_json::json!({
        "id": "discord:999999999999999999", "conversation_id": "slack:T:C:1.000001",
        "channel": "custom", "sender": {"id": "person"}, "text": "hello", "role": "user"
    }))
    .unwrap();
    assert!(message.addressed);
    assert_eq!(message.id.as_ref(), "discord:999999999999999999");
    let value = serde_json::to_value(&message).unwrap();
    assert_eq!(value["id"], "discord:999999999999999999");
    assert_eq!(value["role"], "user");
}

#[test]
fn file_debug_output_does_not_include_bytes() {
    let content = b"private attachment".to_vec();
    let upload = UploadFile {
        filename: "report.txt".into(),
        content: content.clone(),
        title: None,
    };
    let download = DownloadedFile {
        id: "file".into(),
        name: "report.txt".into(),
        content: content.clone(),
        media_type: None,
    };
    for debug in [format!("{upload:?}"), format!("{download:?}")] {
        assert!(debug.contains("content_length: 18"));
        assert!(!debug.contains("private attachment"));
        assert!(!debug.contains(&format!("{content:?}")));
    }
}

#[tokio::test]
async fn nested_reply_and_history_do_not_reacquire_the_conversation_lock() {
    let app = Arc::new(Runtime::new());
    let channel = Arc::new(FakeChannel::default());
    tokio::time::timeout(
        Duration::from_secs(1),
        app.receive(
            channel.clone(),
            incoming("one", "chat"),
            |context| async move {
                assert_eq!(context.history(30).await?.len(), 1);
                context.reply("manual reply").await?;
                assert_eq!(context.conversation.history(None).await?.len(), 2);
                Ok(None)
            },
        ),
    )
    .await
    .unwrap()
    .unwrap();
    assert_eq!(channel.calls.load(Ordering::SeqCst), 1);
    assert_eq!(app.history(&"chat".into(), None).await.unwrap().len(), 2);
}

#[tokio::test]
async fn uncertain_send_never_appends_success_or_retries_claimed_input() {
    let app = Arc::new(Runtime::new());
    let channel = Arc::new(FakeChannel {
        uncertain: true,
        ..Default::default()
    });
    let message = incoming("one", "chat");
    let result = app
        .receive(channel.clone(), message.clone(), |_| async {
            Ok(Some("answer".into()))
        })
        .await;
    assert!(matches!(result, Err(Error::Transport(_))));
    app.receive(channel.clone(), message, |_| async {
        panic!("a claimed message must not run again")
    })
    .await
    .unwrap();
    assert_eq!(channel.calls.load(Ordering::SeqCst), 1);
    assert_eq!(app.history(&"chat".into(), None).await.unwrap().len(), 1);
}

